{
  "name": "CVD气体与温度控制面板",
  "name_en": "CVD Gas & Temperature Control Panel",
  "manufacturer": "",
  "description": "用于化学气相沉积（CVD）实验的控制面板，可管理三路反应气体的流量随时间变化曲线，并设置反应温度设定点；支持将参数保存为“配方”，并可开启/停止运行。",
  "description_en": "A control panel for chemical vapor deposition (CVD) experiments, used to manage time-varying flow profiles for three process gases and set a temperature setpoint; it supports saving/loading recipes and starting/stopping runs.",
  "actions": [
    {
      "action_name": "auto-return_ui_fields",
      "description": "返回界面中用于配置的各项字段内容。",
      "description_en": "Return the UI fields used for configuration."
    },
    {
      "action_name": "auto-save_recipe",
      "description": "将当前界面参数保存为配方文件（含元数据与气体设置），并选择保存位置。",
      "description_en": "Save the current parameters as a recipe file (including metadata and gas settings) and prompt for the save path."
    },
    {
      "action_name": "auto-open_recipe",
      "description": "从配方文件中读取参数并填充到界面中，同时显示配方元数据并设置气体列标签。",
      "description_en": "Load parameters from a recipe file into the interface, display recipe metadata, and set the gas column labels."
    },
    {
      "action_name": "auto-update_plot",
      "description": "更新三路气体流量的曲线显示，用于反映随时间变化的趋势。",
      "description_en": "Update the plots for the three gas flow curves to reflect the time evolution."
    },
    {
      "action_name": "auto-start_recipe",
      "description": "根据当前配方启动运行，并开始更新曲线与界面中的运行状态。",
      "description_en": "Start the process according to the current recipe and begin updating the curves and run status."
    },
    {
      "action_name": "auto-stop_recipe",
      "description": "停止当前配方运行。",
      "description_en": "Stop the currently running recipe."
    },
    {
      "action_name": "auto-apply_setpoints",
      "description": "应用温度设定点等参数到界面显示/对应控制项。",
      "description_en": "Apply setpoints such as the temperature value to the relevant control items and UI display."
    }
  ],
  "tag_hints": [
    "CVD 化学气相沉积",
    "三路气体流量控制",
    "温度设定点",
    "配方（recipe）管理",
    "过程曲线/时序更新",
    "启动与停止运行"
  ]
}
